INSERT INTO public.form (id, title, description, created_at, phase, created_by, tags, metadata, version) VALUES (2, '{"en": "Recommendation Form - Mestrado''s in Computer Science (IME-USP 2026)", "pt": "Formulário de Recomendação - Mestrado em Ciência da Computação (IME-USP 2026)"}', '{"en": "*To be completed by the person recommending the candidate.*

This form allows for the evaluation and recommendation of applications to the Mestrado''s Program in Computer Science at IME-USP. **All information provided on this form is confidential to the candidate** and assists in the program selection process.
", "pt": "*Para ser preenchido por quem está recomendando o(a) candidato(a).*

Este formulário permite a avaliação e recomendação de candidatura ao Programa de Mestrado em Ciência da Computação do IME-USP. **Todas as informações fornecidas neste formulário são sigilosos para o/a candidato/a** e ajudam o processo de seleção de ingressantes no programa.
"}', '2026-10-16 18:16:32.912101', 'Registration', NULL, '{"Ano": "2026", "Edital": "mestrado", "Publico": "recomendadores"}', '{"__message__": "entered by the system"}', 1);


