INSERT INTO public.form_field (id, form_id, section_id, label, name, description, type, placeholder, required, disabled, validation, error_message, prefix, "position", is_active, version) VALUES (19, 1, 3, '{"en": "Lattes CV", "pt": "Currículo Lattes"}', 'lattes-cv', '{"en": "
