INSERT INTO public.form_field (id, form_id, section_id, label, name, description, type, placeholder, required, disabled, validation, error_message, prefix, "position", is_active, version) VALUES (22, 1, 3, '{"en": "Year of Graduation", "pt": "Ano de graduação"}', 'year-of-graduation', '{"en": "Year of graduation as informed in the previous item.", "pt": "Ano de obtenção do diploma de graduação informado no item anterior"}', 'Text', 'YYYY', true, false, '\d{4}', '{"en": "This field only accepts valid years", "pt": "Este campo apenas aceita anos válidos"}', NULL, 3, true, 1);
INSERT INTO public.form_field (id, form_id, section_id, label, name, description, type, placeholder, required, disabled, validation, error_message, prefix, "position", is_active, version) VALUES (23, 1, 3, '{"en": "Institution where you obtained your undergraduate degree", "pt": "Instituição de ensino de graduação"}', 'institution', '{"en": "
